13	
14	const BASE = process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`;
15	
16	async function must(res: Promise<APIResponse>, what: string): Promise<void> {
17	  const r = await res;
18	  if (!r.ok()) {
19	    const body = (await r.text().catch(() => '')).slice(0, 500);
20	    throw new Error(`seed contract broken: ${what} returned HTTP ${r.status()} — ${body}`);
21	  }
22	}
