1	import React, { useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	import { useJsonResource } from '../../ui/useJsonResource';
4	
5	// Clients feature: add a client (name + email) and list every client. Opening a client
6	// (client-open-<id>) reveals the projects being done for them — the client's own projects listing,
7	// scoped via its /api/clients/<id>/projects endpoint. Owns its own state; talks to its own
8	// /api/clients endpoints. data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string; outstanding: number };
10	// How the clients list is ordered: alphabetically by name, or by how much each client still owes.
11	type SortKey = 'name' | 'outstanding';
12	type Project = { id: number; name: string; clientId: number; clientName: string };
13	type Contact = {
14	  id: number;
15	  clientId: number;
16	  name: string;
17	  email: string;
18	  role: string;
19	  primary: boolean;
20	};
21	type ClientSummary = { projectCount: number; contactCount: number };
22	type StatementInvoice = { id: number; projectId: number; amountDue: number };
23	type StatementProject = { projectId: number; invoices: StatementInvoice[]; subtotal: number };
24	type ClientStatement = {
25	  invoices: StatementInvoice[];
26	  projects: StatementProject[];
27	  outstandingTotal: number;
28	};
29	
30	// Money, the way every invoice figure is shown across the app: a dollar sign and two decimals.
31	function money(amount: number): string {
32	  return `$${Number(amount).toLocaleString('en-US', {
33	    minimumFractionDigits: 2,
34	    maximumFractionDigits: 2,
35	  })}`;
36	}
37	
38	// Every client (and contact) needs a proper email. Same shape the server enforces (see CreateClient
39	// / CreateContact) so the UI and the API agree on what "valid" means.
40	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
41	function isValidEmail(value: string): boolean {
42	  return EMAIL_RE.test(value.trim());
43	}
44	
45	// A client's statement: all of their invoices in one place, each with what is still owed on it, and
46	// the total still owed across them all. Kept behind an opener so the client detail stays compact.
47	// Owns its own statement state, scoped to the one client it is showing; talks to that client's own
48	// /api/clients/<id>/statement endpoint.
49	function ClientStatement({ client }: { client: Client }) {
50	  const [statement] = useJsonResource<ClientStatement | null>(
51	    `/api/clients/${client.id}/statement`,
52	    null,
53	  );
54	  const [open, setOpen] = useState(false);
55	
56	  return (
57	    <section data-testid="client-statement">
58	      <button data-testid="client-statement-open" onClick={() => setOpen(true)}>
59	        Statement
60	      </button>
61	      {open && statement && (
62	        <>
63	          <table data-testid="client-statement-table">
64	            {statement.projects.map((project) => (
65	              <tbody
66	                key={project.projectId}
67	                data-testid={`statement-project-${project.projectId}`}
68	              >
69	                {project.invoices.map((inv) => (
70	                  <tr key={inv.id} data-testid={`statement-invoice-row-${inv.id}`}>
71	                    <td data-testid="statement-invoice-due">{money(inv.amountDue)}</td>
72	                  </tr>
73	                ))}
74	                <tr data-testid="statement-project-subtotal-row">
75	                  <td data-testid="statement-project-subtotal">{money(project.subtotal)}</td>
76	                </tr>
77	              </tbody>
78	            ))}
79	          </table>
80	          <p data-testid="client-outstanding-total">{money(statement.outstandingTotal)}</p>
81	        </>
82	      )}
83	    </section>
84	  );
85	}
86	
87	// Recording one lump sum a client paid, split across several of their open invoices. Opening the
88	// form lists each open invoice with a box for the share of the lump sum applied to it
89	// (payment-alloc-<invoiceId>); submitting records one payment per share, so every invoice's balance
90	// then reflects what was put against it. Owns its own form state, scoped to the one client; reads the
91	// client's statement for the open invoices and talks to that client's own /api/clients/<id>/payments
92	// endpoint.
93	function ClientPayment({ client }: { client: Client }) {
94	  const [statement, reload] = useJsonResource<ClientStatement | null>(
95	    `/api/clients/${client.id}/statement`,
96	    null,
97	  );
98	  const [open, setOpen] = useState(false);
99	  const [amount, setAmount] = useState('');
100	  const [date, setDate] = useState('');
101	  // The share typed against each invoice, held as raw strings keyed by invoice id so the inputs stay
102	  // controlled.
103	  const [allocations, setAllocations] = useState<Record<number, string>>({});
104	
105	  const openInvoices = (statement?.invoices ?? []).filter((inv) => inv.amountDue > 0);
106	
107	  async function submit(e: React.FormEvent) {
108	    e.preventDefault();
109	    if (date.trim() === '') {
110	      return;
111	    }
112	    const shares = openInvoices
113	      .map((inv) => ({ invoiceId: inv.id, amount: Number(allocations[inv.id]) }))
114	      .filter((s) => Number.isFinite(s.amount) && s.amount > 0);
115	    if (shares.length === 0) {
116	      return;
117	    }
118	    await fetch(`/api/clients/${client.id}/payments`, {
119	      method: 'POST',
120	      headers: { 'Content-Type': 'application/json' },
121	      body: JSON.stringify({ amount: Number(amount), date, allocations: shares }),
122	    });
123	    setOpen(false);
124	    setAmount('');
125	    setDate('');
126	    setAllocations({});
127	    await reload();
128	  }
129	
130	  return (
131	    <section data-testid="client-payment">
132	      <button data-testid="client-record-payment" type="button" onClick={() => setOpen(true)}>
133	        Record payment
134	      </button>
135	      {open && (
136	        <form data-testid="payment-form" onSubmit={submit}>
137	          <input
138	            data-testid="payment-form-amount"
139	            placeholder="Amount paid"
140	            value={amount}
141	            onChange={(e) => setAmount(e.target.value)}
142	          />
143	          <input
144	            data-testid="payment-form-date"
145	            type="date"
146	            value={date}
147	            onChange={(e) => setDate(e.target.value)}
148	          />
149	          <table data-testid="payment-alloc-table">
150	            <tbody>
151	              {openInvoices.map((inv) => (
152	                <tr key={inv.id} data-testid={`payment-alloc-row-${inv.id}`}>
153	                  <td data-testid="payment-alloc-due">{money(inv.amountDue)}</td>
154	                  <td>
155	                    <input
156	                      data-testid={`payment-alloc-${inv.id}`}
157	                      placeholder="Applied to this invoice"
158	                      value={allocations[inv.id] ?? ''}
159	                      onChange={(e) =>
160	                        setAllocations((prev) => ({ ...prev, [inv.id]: e.target.value }))
161	                      }
162	                    />
163	                  </td>
164	                </tr>
165	              ))}
166	            </tbody>
167	          </table>
168	          <button data-testid="payment-form-submit" type="submit">
169	            Record payment
170	          </button>
171	        </form>
172	      )}
173	    </section>
174	  );
175	}
176	
177	// A client's at-a-glance counts: how many projects and contacts are kept for them. Owns its own
178	// summary state, scoped to the one client it is showing; talks to that client's own
179	// /api/clients/<id>/summary endpoint.
180	function ClientSummaryBadges({ client }: { client: Client }) {
181	  const [summary] = useJsonResource<ClientSummary>(`/api/clients/${client.id}/summary`, {
182	    projectCount: 0,
183	    contactCount: 0,
184	  });
185	
186	  return (
187	    <section data-testid="client-summary">
188	      <span data-testid="client-projects-count">{summary.projectCount}</span>
189	      <span data-testid="client-contacts-count">{summary.contactCount}</span>
190	    </section>
191	  );
192	}
193	
194	// The add-a-contact form: name, email and role, all required, with the same email check the server
195	// runs. Owns only its own field state and clears itself once the parent has taken the new contact.
196	function ContactForm({
197	  onAdd,
198	}: {
199	  onAdd: (contact: { name: string; email: string; role: string }) => Promise<void>;
200	}) {
201	  const [name, setName] = useState('');
202	  const [email, setEmail] = useState('');
203	  const [role, setRole] = useState('');
204	  const [emailError, setEmailError] = useState('');
205	
206	  async function submit(e: React.FormEvent) {
207	    e.preventDefault();
208	    if (!name.trim() || !email.trim() || !role.trim()) {
209	      return;
210	    }
211	    if (!isValidEmail(email)) {
212	      setEmailError('Enter a valid email address.');
213	      return;
214	    }
215	    setEmailError('');
216	    await onAdd({ name, email, role });
217	    setName('');
218	    setEmail('');
219	    setRole('');
220	  }
221	
222	  return (
223	    <form data-testid="contact-form" onSubmit={submit}>
224	      <input
225	        data-testid="contact-form-name"
226	        placeholder="Name"
227	        value={name}
228	        onChange={(e) => setName(e.target.value)}
229	      />
230	      <input
231	        data-testid="contact-form-email"
232	        placeholder="Email"
233	        value={email}
234	        onChange={(e) => setEmail(e.target.value)}
235	      />
236	      {emailError && (
237	        <p data-testid="contact-form-email-error" role="alert">
238	          {emailError}
239	        </p>
240	      )}
241	      <input
242	        data-testid="contact-form-role"
243	        placeholder="Role"
244	        value={role}
245	        onChange={(e) => setRole(e.target.value)}
246	      />
247	      <button data-testid="contact-form-submit" type="submit">
248	        Add contact
249	      </button>
250	    </form>
251	  );
252	}
253	
254	// The contacts list itself: a row per contact with a control to promote it to the client's primary.
255	function ContactsTable({
256	  contacts,
257	  onMakePrimary,
258	}: {
259	  contacts: Contact[];
260	  onMakePrimary: (id: number) => void;
261	}) {
262	  return (
263	    <table data-testid="client-contacts-table">
264	      <tbody>
265	        {contacts.map((ct) => (
266	          <tr key={ct.id} data-testid={`contact-row-${ct.id}`}>
267	            <td data-testid="contact-name">{ct.name}</td>
268	            <td data-testid="contact-email">{ct.email}</td>
269	            <td data-testid="contact-role">{ct.role}</td>
270	            <td>
271	              <button data-testid={`contact-primary-${ct.id}`} onClick={() => onMakePrimary(ct.id)}>
272	                Make primary
273	              </button>
274	            </td>
275	          </tr>
276	        ))}
277	      </tbody>
278	    </table>
279	  );
280	}
281	
282	// A client's contacts: the people the user keeps for them (name, email, role), with a form to add
283	// another. Owns its own contact state, scoped to the one client it is showing; talks to that
284	// client's own /api/clients/<id>/contacts endpoints. The form and the table are their own pieces so
285	// this stays a thin coordinator: load, add, promote, show who is primary.
286	function ClientContacts({ client }: { client: Client }) {
287	  const [contacts, reload] = useJsonResource<Contact[]>(`/api/clients/${client.id}/contacts`, []);
288	
289	  async function addContact(contact: { name: string; email: string; role: string }) {
290	    await fetch(`/api/clients/${client.id}/contacts`, {
291	      method: 'POST',
292	      headers: { 'Content-Type': 'application/json' },
293	      body: JSON.stringify(contact),
294	    });
295	    await reload();
296	  }
297	
298	  // Pick this contact as the client's one main contact, then refresh so the new primary shows.
299	  async function makePrimary(id: number) {
300	    await fetch(`/api/contacts/${id}/primary`, { method: 'POST' });
301	    await reload();
302	  }
303	
304	  const primary = contacts.find((ct) => ct.primary) ?? null;
305	
306	  return (
307	    <section data-testid="client-contacts">
308	      <p data-testid="client-primary-contact">{primary ? primary.name : ''}</p>
309	      <ContactForm onAdd={addContact} />
310	      <ContactsTable contacts={contacts} onMakePrimary={makePrimary} />
311	    </section>
312	  );
313	}
314	
315	// A client's detail: the projects being done for them. Owns its own project state, scoped to the one
316	// client it is showing. Reuses the project-row-<id>/project-name anchors in a client-scoped table.
317	// Shows only the client's ACTIVE projects by default (scope=active); the show-all toggle asks the
318	// server for everything (scope=all), so the finished and hidden (archived) ones appear too.
319	function ClientProjects({ client }: { client: Client }) {
320	  const [showAll, setShowAll] = useState(false);
321	  const [projects] = useJsonResource<Project[]>(
322	    `/api/clients/${client.id}/projects?scope=${showAll ? 'all' : 'active'}`,
323	    [],
324	  );
325	
326	  return (
327	    <section data-testid="client-projects">
328	      <button data-testid="client-projects-show-all" onClick={() => setShowAll((v) => !v)}>
329	        {showAll ? 'Show only active' : 'Show finished and hidden too'}
330	      </button>
331	      <table data-testid="client-projects-table">
332	        <tbody>
333	          {projects.map((p) => (
334	            <tr key={p.id} data-testid={`project-row-${p.id}`}>
335	              <td data-testid="project-name">{p.name}</td>
336	            </tr>
337	          ))}
338	        </tbody>
339	      </table>
340	    </section>
341	  );
342	}
343	
344	// A name-and-email form for a client, used to add one and reusable for correcting one. `testid` is
345	// the anchor prefix (its fields are `${testid}-name` / `-email` / `-email-error` / `-submit`), so a
346	// second instance (e.g. an edit form) just passes a different prefix. Validates the email format the
347	// way the server does; `onSubmit` returns an error string to show (e.g. a duplicate the server
348	// rejected) or null on success, in which case the form clears back to its initial values.
349	function ClientForm({
350	  testid,
351	  submitLabel,
352	  initial = { name: '', email: '' },
353	  onSubmit,
354	}: {
355	  testid: string;
356	  submitLabel: string;
357	  initial?: { name: string; email: string };
358	  onSubmit: (values: { name: string; email: string }) => Promise<string | null>;
359	}) {
360	  const [name, setName] = useState(initial.name);
361	  const [email, setEmail] = useState(initial.email);
362	  const [emailError, setEmailError] = useState('');
363	
364	  async function submit(e: React.FormEvent) {
365	    e.preventDefault();
366	    if (!isValidEmail(email)) {
367	      setEmailError('Enter a valid email address.');
368	      return;
369	    }
370	    const error = await onSubmit({ name, email });
371	    if (error) {
372	      setEmailError(error);
373	      return;
374	    }
375	    setEmailError('');
376	    setName(initial.name);
377	    setEmail(initial.email);
378	  }
379	
380	  return (
381	    <form data-testid={testid} onSubmit={submit}>
382	      <input
383	        data-testid={`${testid}-name`}
384	        placeholder="Name"
385	        value={name}
386	        onChange={(e) => setName(e.target.value)}
387	      />
388	      <input
389	        data-testid={`${testid}-email`}
390	        placeholder="Email"
391	        value={email}
392	        onChange={(e) => setEmail(e.target.value)}
393	      />
394	      {emailError && (
395	        <p data-testid={`${testid}-email-error`} role="alert">
396	          {emailError}
397	        </p>
398	      )}
399	      <button data-testid={`${testid}-submit`} type="submit">
400	        {submitLabel}
401	      </button>
402	    </form>
