474	function ClientsPage() {
475	  const [clients, reload] = useJsonResource<Client[]>('/api/clients', []);
476	  // The tucked-away clients, loaded alongside the live list so the "show archived" toggle can reveal
477	  // them; kept separate from `clients` so the default list stays exactly the live ones.
478	  const [archived, reloadArchived] = useJsonResource<Client[]>('/api/clients/archived', []);
479	  // Whether the archived clients are on show (so one can be brought back) or tucked away by default.
480	  const [showArchived, setShowArchived] = useState(false);
481	  // Client-side name filter: the list can get long, so a search box narrows it. Case-insensitive
482	  // substring match on the client name; an empty box shows everyone.
483	  const [search, setSearch] = useState('');
484	  // How the list is ordered: by name (default) or by how much each client owes (most first).
485	  const [sort, setSort] = useState<SortKey>('name');
486	  const [openId, setOpenId] = useState<number | null>(null);
487	  // Which client (if any) is being corrected: opening the edit form seeds it with that client's
488	  // current name and email so the user tweaks rather than retypes.
489	  const [editingId, setEditingId] = useState<number | null>(null);
490	
491	  // Two clients cannot share an email; the server rejects a duplicate, so surface it and keep the
492	  // form as-is rather than clearing or reloading (nothing was added).
493	  async function addClient(values: { name: string; email: string }): Promise<string | null> {
494	    const res = await fetch('/api/clients', {
495	      method: 'POST',
496	      headers: { 'Content-Type': 'application/json' },
497	      body: JSON.stringify(values),
498	    });
499	    if (!res.ok) {
500	      return 'A client with this email already exists.';
501	    }
502	    await reload();
503	    return null;
504	  }
505	
506	  // Correct a client's name or email. The server rejects a duplicate email (against another
507	  // client), so surface it and keep the form open; on success reload and close the edit form.
508	  async function editClient(
509	    id: number,
510	    values: { name: string; email: string },
511	  ): Promise<string | null> {
512	    const res = await fetch(`/api/clients/${id}`, {
513	      method: 'PUT',
514	      headers: { 'Content-Type': 'application/json' },
515	      body: JSON.stringify(values),
516	    });
517	    if (!res.ok) {
518	      return 'A client with this email already exists.';
519	    }
520	    await reload();
521	    setEditingId(null);
522	    return null;
523	  }
524	
525	  // Tuck a client away: archived clients are retained server-side but drop off this list and out of
526	  // the search. Reloading after archiving is enough — the /api/clients list excludes them.
527	  async function archive(id: number) {
528	    await fetch(`/api/clients/${id}/archive`, { method: 'POST' });
529	    if (openId === id) {
530	      setOpenId(null);
531	    }
532	    if (editingId === id) {
533	      setEditingId(null);
534	    }
535	    await reload();
536	    await reloadArchived();
537	  }
538	
539	  // Bring a tucked-away client back: clearing its archived flag returns it to the live list and drops
540	  // it from the archived one, so refresh both.
541	  async function restore(id: number) {
542	    await fetch(`/api/clients/${id}/restore`, { method: 'POST' });
543	    await reload();
544	    await reloadArchived();
545	  }
546	
547	  const term = search.trim().toLowerCase();
548	  // Filter by the search box, then order: by name ascending, or by outstanding amount descending
549	  // (the client who owes the most first).
550	  const visible = clients
551	    .filter((c) => c.name.toLowerCase().includes(term))
552	    .sort((a, b) =>
553	      sort === 'outstanding' ? b.outstanding - a.outstanding : a.name.localeCompare(b.name),
554	    );
555	  const open = clients.find((c) => c.id === openId) ?? null;
556	  const editing = clients.find((c) => c.id === editingId) ?? null;
557	
558	  return (
559	    <section data-testid="clients">
560	      <input
561	        data-testid="client-search"
562	        placeholder="Search clients by name"
563	        value={search}
564	        onChange={(e) => setSearch(e.target.value)}
565	      />
566	      <select
567	        data-testid="client-sort"
568	        value={sort}
569	        onChange={(e) => setSort(e.target.value as SortKey)}
570	      >
571	        <option value="name">Name</option>
572	        <option value="outstanding">Outstanding</option>
573	      </select>
574	      <ClientForm testid="client-form" submitLabel="Add client" onSubmit={addClient} />
575	
576	      <button data-testid="clients-show-archived" onClick={() => setShowArchived((v) => !v)}>
577	        {showArchived ? 'Hide archived' : 'Show archived'}
578	      </button>
579	      {showArchived && <ArchivedClients clients={archived} onRestore={restore} />}
580	
581	      {clients.length === 0 ? (
582	        <p data-testid="clients-empty">No clients yet.</p>
583	      ) : (
584	        <ClientsTable
585	          clients={visible}
586	          onOpen={setOpenId}
587	          onEdit={setEditingId}
588	          onArchive={archive}
589	        />
590	      )}
591	
592	      {editing && (
593	        <ClientForm
594	          key={`edit-${editing.id}`}
595	          testid="client-edit-form"
596	          submitLabel="Save changes"
597	          initial={{ name: editing.name, email: editing.email }}
598	          onSubmit={(values) => editClient(editing.id, values)}
599	        />
600	      )}
601	
602	      {open && <ClientSummaryBadges key={`summary-${open.id}`} client={open} />}
603	      {open && <ClientStatement key={`statement-${open.id}`} client={open} />}
604	      {open && <ClientPayment key={`payment-${open.id}`} client={open} />}
605	      {open && <ClientContacts key={`contacts-${open.id}`} client={open} />}
606	      {open && <ClientProjects key={open.id} client={open} />}
607	    </section>
608	  );
609	}
